39	std::string EscapeJsonString(const std::string& input) {
40	  std::string out;
41	  out.reserve(input.size() + 8);
42	  for (const char c : input) {
43	    switch (c) {
44	      case '"':
45	        out += "\\\"";
46	        break;
47	      case '\\':
48	        out += "\\\\";
49	        break;
50	      case '\b':
51	        out += "\\b";
52	        break;
53	      case '\f':
54	        out += "\\f";
55	        break;
56	      case '\n':
57	        out += "\\n";
58	        break;
59	      case '\r':
60	        out += "\\r";
61	        break;
62	      case '\t':
63	        out += "\\t";
64	        break;
65	      default:
66	        out += c;
67	        break;
68	    }
69	  }
70	  return out;
71	}
72	
73	std::string FormatDouble(double v) {
74	  if (std::isnan(v) || std::isinf(v)) {
75	    return "0.0";
76	  }
77	  std::ostringstream ss;
78	  ss << std::setprecision(8) << v;
79	  std::string s = ss.str();
80	  return s;
81	}
82	
83	// -------------------------------------------------------------
84	// 极轻量但健壮的递归下降 JSON 抽象节点树
85	// -------------------------------------------------------------
86	enum class JsonType { Null, Bool, Number, String, Array, Object };
87	
88	struct JsonValue {
89	  JsonType type = JsonType::Null;
90	  bool bool_val = false;
91	  double num_val = 0.0;
92	  std::string str_val;
93	  std::vector<JsonValue> arr_val;
94	  std::unordered_map<std::string, JsonValue> obj_val;
95	
96	  bool IsObject() const { return type == JsonType::Object; }
97	  bool IsArray() const { return type == JsonType::Array; }
98	  bool IsString() const { return type == JsonType::String; }
99	  bool IsNumber() const { return type == JsonType::Number; }
100	  bool IsBool() const { return type == JsonType::Bool; }
101	
102	  const JsonValue* Find(const std::string& key) const {
103	    if (type != JsonType::Object) return nullptr;
104	    auto it = obj_val.find(key);
105	    if (it != obj_val.end()) {
106	      return &it->second;
107	    }
108	    return nullptr;
109	  }
110	};
111	
112	class MiniJsonParser {
113	 public:
114	  explicit MiniJsonParser(std::string_view text) : text_(text), pos_(0) {}
115	
116	  std::optional<JsonValue> Parse() {
117	    SkipWhitespace();
118	    if (pos_ >= text_.size()) {
119	      return std::nullopt;
120	    }
121	    auto val = ParseValue();
122	    if (!val.has_value()) {
123	      return std::nullopt;
124	    }
125	    SkipWhitespace();
126	    if (pos_ != text_.size()) {
127	      return std::nullopt;  // 尾部有多余非空白字符
128	    }
129	    return val;
130	  }
131	
132	 private:
133	  char Peek() const {
134	    if (pos_ < text_.size()) return text_[pos_];
135	    return '\0';
136	  }
137	
138	  char Next() {
139	    if (pos_ < text_.size()) return text_[pos_++];
140	    return '\0';
141	  }
142	
143	  void SkipWhitespace() {
144	    while (pos_ < text_.size()) {
145	      const char c = text_[pos_];
146	      if (c == ' ' || c == '\t' || c == '\r' || c == '\n') {
147	        ++pos_;
148	      } else {
149	        break;
150	      }
151	    }
152	  }
153	
154	  std::optional<JsonValue> ParseValue() {
155	    SkipWhitespace();
156	    if (pos_ >= text_.size()) return std::nullopt;
157	    char c = Peek();
158	    if (c == '{') return ParseObject();
159	    if (c == '[') return ParseArray();
160	    if (c == '"') return ParseString();
161	    if (c == 't' || c == 'f') return ParseBool();
162	    if (c == 'n') return ParseNull();
163	    if (c == '-' || (c >= '0' && c <= '9')) return ParseNumber();
164	    return std::nullopt;
165	  }
166	
167	  std::optional<JsonValue> ParseObject() {
168	    if (Next() != '{') return std::nullopt;
169	    JsonValue val;
170	    val.type = JsonType::Object;
171	    SkipWhitespace();
172	    if (Peek() == '}') {
173	      Next();
174	      return val;
175	    }
176	    while (pos_ < text_.size()) {
177	      SkipWhitespace();
178	      if (Peek() != '"') return std::nullopt;
179	      auto key_val = ParseString();
180	      if (!key_val.has_value()) return std::nullopt;
181	      std::string key = key_val->str_val;
182	
183	      SkipWhitespace();
184	      if (Next() != ':') return std::nullopt;
185	
186	      auto member_val = ParseValue();
187	      if (!member_val.has_value()) return std::nullopt;
188	
189	      val.obj_val.emplace(std::move(key), std::move(*member_val));
190	
191	      SkipWhitespace();
192	      char sep = Peek();
193	      if (sep == ',') {
194	        Next();
195	      } else if (sep == '}') {
196	        Next();
197	        return val;
198	      } else {
199	        return std::nullopt;
200	      }
201	    }
202	    return std::nullopt;
203	  }
204	
205	  std::optional<JsonValue> ParseArray() {
206	    if (Next() != '[') return std::nullopt;
207	    JsonValue val;
208	    val.type = JsonType::Array;
209	    SkipWhitespace();
210	    if (Peek() == ']') {
211	      Next();
212	      return val;
213	    }
214	    while (pos_ < text_.size()) {
215	      auto item = ParseValue();
216	      if (!item.has_value()) return std::nullopt;
217	      val.arr_val.push_back(std::move(*item));
218	
219	      SkipWhitespace();
220	      char sep = Peek();
221	      if (sep == ',') {
222	        Next();
223	      } else if (sep == ']') {
224	        Next();
225	        return val;
226	      } else {
227	        return std::nullopt;
228	      }
229	    }
230	    return std::nullopt;
231	  }
232	
233	  std::optional<JsonValue> ParseString() {
234	    if (Next() != '"') return std::nullopt;
235	    std::string s;
236	    while (pos_ < text_.size()) {
237	      char c = Next();
238	      if (c == '"') {
239	        JsonValue v;
240	        v.type = JsonType::String;
241	        v.str_val = std::move(s);
242	        return v;
243	      }
244	      if (c == '\\') {
245	        if (pos_ >= text_.size()) return std::nullopt;
246	        char esc = Next();
247	        switch (esc) {
248	          case '"':
249	            s += '"';
250	            break;
251	          case '\\':
252	            s += '\\';
253	            break;
254	          case '/':
255	            s += '/';
256	            break;
257	          case 'b':
258	            s += '\b';
259	            break;
260	          case 'f':
261	            s += '\f';
262	            break;
263	          case 'n':
264	            s += '\n';
265	            break;
266	          case 'r':
267	            s += '\r';
268	            break;
269	          case 't':
270	            s += '\t';
271	            break;
272	          case 'u': {
273	            // 跳过 4 位 hex，简化处理
274	            if (pos_ + 4 > text_.size()) return std::nullopt;
275	            pos_ += 4;
276	            s += '?';
277	            break;
278	          }
279	          default:
280	            s += esc;
281	            break;
282	        }
283	      } else {
284	        s += c;
285	      }
286	    }
287	    return std::nullopt;
288	  }
289	
290	  std::optional<JsonValue> ParseNumber() {
291	    size_t start = pos_;
292	    if (Peek() == '-') Next();
293	    while (pos_ < text_.size() && (std::isdigit(static_cast<unsigned char>(text_[pos_])) ||
294	                                   text_[pos_] == '.' || text_[pos_] == 'e' ||
295	                                   text_[pos_] == 'E' || text_[pos_] == '+' ||
296	                                   text_[pos_] == '-')) {
297	      Next();
298	    }
299	    std::string sub(text_.substr(start, pos_ - start));
300	    try {
301	      size_t processed = 0;
302	      double d = std::stod(sub, &processed);
303	      if (processed != sub.size() || std::isnan(d) || std::isinf(d)) {
304	        return std::nullopt;
305	      }
306	      JsonValue v;
307	      v.type = JsonType::Number;
308	      v.num_val = d;
309	      return v;
310	    } catch (...) {
311	      return std::nullopt;
312	    }
313	  }
314	
315	  std::optional<JsonValue> ParseBool() {
316	    if (text_.substr(pos_, 4) == "true") {
317	      pos_ += 4;
318	      JsonValue v;
319	      v.type = JsonType::Bool;
320	      v.bool_val = true;
321	      return v;
322	    }
323	    if (text_.substr(pos_, 5) == "false") {
324	      pos_ += 5;
325	      JsonValue v;
326	      v.type = JsonType::Bool;
327	      v.bool_val = false;
328	      return v;
329	    }
330	    return std::nullopt;
331	  }
332	
333	  std::optional<JsonValue> ParseNull() {
334	    if (text_.substr(pos_, 4) == "null") {
335	      pos_ += 4;
336	      JsonValue v;
337	      v.type = JsonType::Null;
338	      return v;
339	    }
340	    return std::nullopt;
341	  }
342	
343	  std::string_view text_;
344	  size_t pos_;
345	};
