496	std::optional<VehicleStateReport> DeserializeVda5050State(const std::string& json_str) {
497	  if (json_str.empty()) {
498	    return std::nullopt;
499	  }
500	  MiniJsonParser parser(json_str);
501	  auto root = parser.Parse();
502	  if (!root.has_value() || !root->IsObject()) {
503	    return std::nullopt;
504	  }
505	
506	  // 必须字段检查: serialNumber
507	  const auto* serial_val = root->Find("serialNumber");
508	  if (!serial_val || !serial_val->IsString() || serial_val->str_val.empty()) {
509	    return std::nullopt;
510	  }
511	
512	  // agvPosition 必须存在且合法
513	  const auto* pos_val = root->Find("agvPosition");
514	  if (!pos_val || !pos_val->IsObject()) {
515	    return std::nullopt;
516	  }
517	  const auto* x_val = pos_val->Find("x");
518	  const auto* y_val = pos_val->Find("y");
519	  const auto* theta_val = pos_val->Find("theta");
520	  if (!x_val || !x_val->IsNumber() || !y_val || !y_val->IsNumber() ||
521	      !theta_val || !theta_val->IsNumber()) {
522	    return std::nullopt;
523	  }
524	
525	  VehicleStateReport report;
526	  report.vehicle_id = serial_val->str_val;
527	  report.x = x_val->num_val;
528	  report.y = y_val->num_val;
529	  report.yaw = theta_val->num_val;
530	
531	  // orderId
532	  const auto* order_id_val = root->Find("orderId");
533	  if (order_id_val && order_id_val->IsString()) {
534	    report.order_id = order_id_val->str_val;
535	  }
536	
537	  // lastNodeId
538	  const auto* last_node_val = root->Find("lastNodeId");
539	  if (last_node_val && last_node_val->IsString()) {
540	    report.last_node_id = last_node_val->str_val;
541	  }
542	
543	  // lastNodeSequenceId
544	  const auto* last_seq_val = root->Find("lastNodeSequenceId");
545	  if (last_seq_val && last_seq_val->IsNumber()) {
546	    report.last_node_sequence_id = static_cast<uint32_t>(last_seq_val->num_val);
547	  }
548	
549	  // batteryState
550	  const auto* battery_val = root->Find("batteryState");
551	  if (battery_val && battery_val->IsObject()) {
552	    const auto* charge_val = battery_val->Find("batteryCharge");
553	    if (charge_val && charge_val->IsNumber()) {
554	      report.battery_percent = charge_val->num_val;
555	    }
556	    const auto* charging_val = battery_val->Find("charging");
557	    if (charging_val && charging_val->IsBool()) {
558	      report.is_charging = charging_val->bool_val;
559	    }
560	  }
561	
562	  // safetyState
563	  const auto* safety_val = root->Find("safetyState");
564	  if (safety_val && safety_val->IsObject()) {
565	    const auto* estop_val = safety_val->Find("eStop");
566	    if (estop_val) {
567	      if (estop_val->IsBool()) {
568	        report.estop_active = estop_val->bool_val;
569	      } else if (estop_val->IsString()) {
570	        // VDA 5050 常见: "none", "autoAck", "manual", "remote"
571	        report.estop_active = (estop_val->str_val != "none" && !estop_val->str_val.empty());
572	      }
573	    }
574	  }
575	
576	  // operatingMode
577	  const auto* mode_val = root->Find("operatingMode");
578	  if (mode_val && mode_val->IsString() && !mode_val->str_val.empty()) {
579	    report.operating_mode = mode_val->str_val;
580	  }
581	
582	  // errors
583	  const auto* errors_val = root->Find("errors");
584	  if (errors_val && errors_val->IsArray()) {
585	    for (const auto& err_item : errors_val->arr_val) {
586	      if (err_item.IsObject()) {
587	        std::string err_type;
588	        std::string err_desc;
589	        const auto* t = err_item.Find("errorType");
590	        if (t && t->IsString()) err_type = t->str_val;
591	        const auto* d = err_item.Find("errorDescription");
592	        if (d && d->IsString()) err_desc = d->str_val;
593	
594	        if (!err_type.empty() && !err_desc.empty()) {
595	          report.active_errors.push_back(err_type + ": " + err_desc);
596	        } else if (!err_type.empty()) {
597	          report.active_errors.push_back(err_type);
598	        } else if (!err_desc.empty()) {
599	          report.active_errors.push_back(err_desc);
600	        }
601	      }
602	    }
603	  }
604	
605	  report.online = true;
606	  report.last_report_time = std::chrono::steady_clock::now();
607	  return report;
608	}
