// 获取当前 UTC 时间 ISO 8601 字符串，例如 2026-10-20T12:00:00.000Z
std::string CurrentIsoTimestamp() {
  const auto now = std::chrono::system_clock::now();
  const auto millis = std::chrono::duration_cast<std::chrono::milliseconds>(
                          now.time_since_epoch()) %
                      1000;
  const std::time_t timer = std::chrono::system_clock::to_time_t(now);
  std::tm tm_buf{};
#if defined(_WIN32)
  gmtime_s(&tm_buf, &timer);
#else
  gmtime_r(&timer, &tm_buf);
#endif
  std::ostringstream ss;
  ss << std::put_time(&tm_buf, "%Y-%m-%dT%H:%M:%S") << '.'
     << std::setfill('0') << std::setw(3) << millis.count() << 'Z';
  return ss.str();
}

std::string EscapeJsonString(const std::string& input) {
  std::string out;
  out.reserve(input.size() + 8);
  for (const char c : input) {
    switch (c) {
      case '"':
        out += "\\\"";
        break;
      case '\\':
        out += "\\\\";
        break;
      case '\b':
        out += "\\b";
        break;
      case '\f':
        out += "\\f";
        break;
      case '\n':
        out += "\\n";
        break;
      case '\r':
        out += "\\r";
        break;
      case '\t':
        out += "\\t";
        break;
      default:
        out += c;
        break;
    }
  }
  return out;
}

std::string FormatDouble(double v) {
  if (std::isnan(v) || std::isinf(v)) {
    return "0.0";
  }
  std::ostringstream ss;
  ss << std::setprecision(8) << v;
  std::string s = ss.str();
  return s;
}

// -------------------------------------------------------------
// 极轻量但健壮的递归下降 JSON 抽象节点树
// -------------------------------------------------------------
enum class JsonType { Null, Bool, Number, String, Array, Object };

struct JsonValue {
  JsonType type = JsonType::Null;
  bool bool_val = false;
  double num_val = 0.0;
  std::string str_val;
  std::vector<JsonValue> arr_val;
  std::unordered_map<std::string, JsonValue> obj_val;

  bool IsObject() const { return type == JsonType::Object; }
  bool IsArray() const { return type == JsonType::Array; }
  bool IsString() const { return type == JsonType::String; }
  bool IsNumber() const { return type == JsonType::Number; }
  bool IsBool() const { return type == JsonType::Bool; }

  const JsonValue* Find(const std::string& key) const {
    if (type != JsonType::Object) return nullptr;
    auto it = obj_val.find(key);
    if (it != obj_val.end()) {
      return &it->second;
    }
    return nullptr;
  }
};

class MiniJsonParser {
 public:
  explicit MiniJsonParser(std::string_view text) : text_(text), pos_(0) {}

  std::optional<JsonValue> Parse() {
    SkipWhitespace();
    if (pos_ >= text_.size()) {
      return std::nullopt;
    }
    auto val = ParseValue();
    if (!val.has_value()) {
      return std::nullopt;
    }
    SkipWhitespace();
    if (pos_ != text_.size()) {
      return std::nullopt;  // 尾部有多余非空白字符
    }
    return val;
  }

 private:
  char Peek() const {
    if (pos_ < text_.size()) return text_[pos_];
    return '\0';
  }

  char Next() {
    if (pos_ < text_.size()) return text_[pos_++];
    return '\0';
  }

  void SkipWhitespace() {
    while (pos_ < text_.size()) {
      const char c = text_[pos_];
      if (c == ' ' || c == '\t' || c == '\r' || c == '\n') {
        ++pos_;
      } else {
        break;
      }
    }
  }

  std::optional<JsonValue> ParseValue() {
    SkipWhitespace();
    if (pos_ >= text_.size()) return std::nullopt;
    char c = Peek();
    if (c == '{') return ParseObject();
    if (c == '[') return ParseArray();
    if (c == '"') return ParseString();
    if (c == 't' || c == 'f') return ParseBool();
    if (c == 'n') return ParseNull();
    if (c == '-' || (c >= '0' && c <= '9')) return ParseNumber();
    return std::nullopt;
  }

  std::optional<JsonValue> ParseObject() {
    if (Next() != '{') return std::nullopt;
    JsonValue val;
    val.type = JsonType::Object;
    SkipWhitespace();
    if (Peek() == '}') {
      Next();
      return val;
    }
    while (pos_ < text_.size()) {
      SkipWhitespace();
      if (Peek() != '"') return std::nullopt;
      auto key_val = ParseString();
      if (!key_val.has_value()) return std::nullopt;
      std::string key = key_val->str_val;

      SkipWhitespace();
      if (Next() != ':') return std::nullopt;

      auto member_val = ParseValue();
      if (!member_val.has_value()) return std::nullopt;

      val.obj_val.emplace(std::move(key), std::move(*member_val));

      SkipWhitespace();
      char sep = Peek();
      if (sep == ',') {
        Next();
      } else if (sep == '}') {
        Next();
        return val;
      } else {
        return std::nullopt;
      }
    }
    return std::nullopt;
  }

  std::optional<JsonValue> ParseArray() {
    if (Next() != '[') return std::nullopt;
    JsonValue val;
    val.type = JsonType::Array;
    SkipWhitespace();
    if (Peek() == ']') {
      Next();
      return val;
    }
    while (pos_ < text_.size()) {
      auto item = ParseValue();
      if (!item.has_value()) return std::nullopt;
      val.arr_val.push_back(std::move(*item));

      SkipWhitespace();
      char sep = Peek();
      if (sep == ',') {
        Next();
      } else if (sep == ']') {
        Next();
        return val;
      } else {
        return std::nullopt;
      }
    }
    return std::nullopt;
  }

  std::optional<JsonValue> ParseString() {
    if (Next() != '"') return std::nullopt;
    std::string s;
    while (pos_ < text_.size()) {
      char c = Next();
      if (c == '"') {
        JsonValue v;
        v.type = JsonType::String;
        v.str_val = std::move(s);
        return v;
      }
      if (c == '\\') {
        if (pos_ >= text_.size()) return std::nullopt;
        char esc = Next();
        switch (esc) {
          case '"':
            s += '"';
            break;
          case '\\':
            s += '\\';
            break;
          case '/':
            s += '/';
            break;
          case 'b':
            s += '\b';
            break;
          case 'f':
            s += '\f';
            break;
          case 'n':
            s += '\n';
            break;
          case 'r':
            s += '\r';
            break;
          case 't':
            s += '\t';
            break;
          case 'u': {
            // 跳过 4 位 hex，简化处理
            if (pos_ + 4 > text_.size()) return std::nullopt;
            pos_ += 4;
            s += '?';
            break;
          }
          default:
            s += esc;
            break;
        }
      } else {
        s += c;
      }
    }
    return std::nullopt;
  }

  std::optional<JsonValue> ParseNumber() {
    size_t start = pos_;
    if (Peek() == '-') Next();
    while (pos_ < text_.size() && (std::isdigit(static_cast<unsigned char>(text_[pos_])) ||
                                   text_[pos_] == '.' || text_[pos_] == 'e' ||
                                   text_[pos_] == 'E' || text_[pos_] == '+' ||
                                   text_[pos_] == '-')) {
      Next();
    }
    std::string sub(text_.substr(start, pos_ - start));
    try {
      size_t processed = 0;
      double d = std::stod(sub, &processed);
      if (processed != sub.size() || std::isnan(d) || std::isinf(d)) {
        return std::nullopt;
      }
      JsonValue v;
      v.type = JsonType::Number;
      v.num_val = d;
      return v;
    } catch (...) {
      return std::nullopt;
    }
  }

  std::optional<JsonValue> ParseBool() {
    if (text_.substr(pos_, 4) == "true") {
      pos_ += 4;
      JsonValue v;
      v.type = JsonType::Bool;
      v.bool_val = true;
      return v;
    }
    if (text_.substr(pos_, 5) == "false") {
      pos_ += 5;
      JsonValue v;
      v.type = JsonType::Bool;
      v.bool_val = false;
      return v;
    }
    return std::nullopt;
  }

  std::optional<JsonValue> ParseNull() {
    if (text_.substr(pos_, 4) == "null") {
      pos_ += 4;
      JsonValue v;
      v.type = JsonType::Null;
      return v;
    }
    return std::nullopt;
  }

  std::string_view text_;
  size_t pos_;
};

