  ss << "\"serialNumber\":\"" << EscapeJsonString(vehicle_id) << "\",";
  ss << "\"actions\":[";
  for (size_t i = 0; i < actions.size(); ++i) {
    if (i > 0) ss << ",";
    const auto& act = actions[i];
